import { createRouter } from './api/router'
import { createTaskStore } from './data/taskStore'
import { createTaskService } from './services/taskService'
import { config } from './config'

export function createApp() {
  const store = createTaskStore()
  const service = createTaskService(store)
  return { name: config.projectName, router: createRouter(service) }
}

import { createTaskService } from '../services/taskService'

// Transport-independent commands; this is not a running HTTP API.
export function createRouter(service: ReturnType<typeof createTaskService>) {
  return {
    list: () => service.list(),
    create: (id: string, title: unknown) => service.create(id, title),
    complete: (id: string) => service.complete(id),
  }
}

import { completeTask, type Task } from '../domain/task'
import { createTaskStore } from '../data/taskStore'
import { parseTitle } from '../lib/validation'

export function createTaskService(store: ReturnType<typeof createTaskStore>) {
  return {
    create(id: string, input: unknown): Task {
      return store.save({ id, title: parseTitle(input), status: 'open' })
    },
    complete(id: string): Task {
      const task = store.get(id)
      if (!task) throw new Error('Task not found')
      return store.save(completeTask(task))
    },
    list: store.list,
  }
}

import type { Task } from '../domain/task'

// An in-memory adapter for this first-party sample only.
export function createTaskStore() {
  const tasks = new Map<string, Task>()
  return {
    get: (id: string) => tasks.get(id),
    save: (task: Task) => {
      tasks.set(task.id, task)
      return task
    },
    list: () => [...tasks.values()],
  }
}

export type TaskStatus = 'open' | 'done'

export interface Task {
  id: string
  title: string
  status: TaskStatus
}

export function completeTask(task: Task): Task {
  return { ...task, status: 'done' }
}

import { config } from '../config'

export function parseTitle(input: unknown): string {
  if (typeof input !== 'string') {
    throw new Error('A title is required')
  }
  const title = input.trim()
  if (!title || title.length > config.maxTitleLength) {
    throw new Error('Title length is outside the allowed range')
  }
  return title
}

export const config = {
  maxTitleLength: 120,
  projectName: 'Dispatch',
} as const
